namespace Osirion.Blazor.Components;

/// <summary>
/// Pinned Prism release served from cdnjs together with the Subresource Integrity hashes of every file the
/// <see cref="OsirionHtmlRenderer"/> can request from it.
/// </summary>
/// <remarks>
/// The hashes are the official cdnjs values for version 1.29.0, read from
/// <c>https://api.cdnjs.com/libraries/prism/1.29.0?fields=sri</c>. When <see cref="Version"/> is changed, regenerate
/// the table from the same endpoint; a stale hash makes the browser refuse the file, it never loads unverified code.
/// </remarks>
internal static class PrismCdnAssets
{
    /// <summary>The pinned Prism version.</summary>
    internal const string Version = "1.29.0";

    /// <summary>The base address of the pinned release on cdnjs.</summary>
    internal const string BaseUrl = "https://cdnjs.cloudflare.com/ajax/libs/prism/" + Version + "/";

    /// <summary>
    /// Gets the SRI hash for a file of the pinned release.
    /// </summary>
    /// <param name="relativePath">The file path relative to <see cref="BaseUrl"/>.</param>
    /// <param name="integrity">The hash when the file is known.</param>
    /// <returns><see langword="true"/> when the file belongs to the pinned release and has a hash.</returns>
    internal static bool TryGetIntegrity(string relativePath, out string integrity)
    {
        return Hashes.TryGetValue(relativePath, out integrity!);
    }

